<?php require_once '../functions.php';$count=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){if($count>0&&!admin())$err='Admin sudah ada. Silakan login sebagai admin untuk mendaftarkan akun admin tambahan.';else{$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(strlen($pass)<8)$err='Kata sandi minimal 8 karakter.';else{try{$sql=$dbDriver==='pgsql'?"INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'admin') RETURNING id":"INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'admin')";$q=$pdo->prepare($sql);$q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$userId=$dbDriver==='pgsql'?(int)$q->fetchColumn():(int)$pdo->lastInsertId();if($count===0){$_SESSION['user']=['id'=>$userId,'name'=>$name,'email'=>$email,'role'=>'admin'];header('Location: '.app_url('admin/index.php'));exit;}$err='Admin berhasil didaftarkan. Silakan login.';}catch(PDOException $e){$err='Email sudah dipakai.';}}}}header_html('Register admin');?><section class="auth card"><span class="eyebrow">PENGELOLA SISTEM</span><h1>Register admin</h1><p class="muted"><?=$count===0?'Pendaftaran admin pertama tersedia. Setelah akun pertama dibuat, pendaftaran berikutnya hanya bisa dilakukan oleh admin yang sudah login.':'Admin yang aktif dapat membuat akun admin tambahan.'?></p><?php if($err):?><div class="alert"><?=e($err)?></div><?php endif;?><form class="form" method="post"><label>Nama<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Kata sandi (min. 8 karakter)<input type="password" name="password" minlength="8" required></label><button class="button">Daftarkan admin</button></form><p><a href="<?=e(app_url('admin/login.php'))?>">Kembali ke login</a></p></section><?php footer_html();?>
